const plan=$("Planifier la partie").first().json;
const rows=$input.all().map(i=>i.json);
for(const attendu of plan.enigmes_a_ecrire){if(!rows.some(r=>r.session_id===attendu.session_id&&r.etape===attendu.etape&&r.statut===attendu.statut))throw Error('Écriture des énigmes incomplète : vérifier jeu_enigmes');}
return [{json:plan}];

const plan=$("Planifier la partie").first().json;
const rows=$input.all().map(i=>i.json);
for(const attendu of plan.distribution){if(!rows.some(r=>r.session_id===attendu.session_id&&String(r.telegram_chat_id)===attendu.telegram_chat_id&&r.role===attendu.role&&r.camp===attendu.camp))throw Error('Distribution incomplète : vérifier jeu_joueurs avant de lancer');}
return [{json:plan}];

const plan=$('Planifier la partie').first().json;
const distinct=new Map();
$input.all().map(i=>i.json).filter(j=>j.session_id===plan.session_id&&j.telegram_chat_id).sort((a,b)=>Number(a.id)-Number(b.id))
  .forEach(j=>{if(!distinct.has(String(j.telegram_chat_id))) distinct.set(String(j.telegram_chat_id),j)});
const owner=String(plan.session.organisateur_chat_id);
const guests=[...distinct.keys()].filter(chat=>chat!==owner);
const accepte=distinct.has(plan.telegram_chat_id)&&(plan.telegram_chat_id===owner||guests.indexOf(plan.telegram_chat_id)>=0&&guests.indexOf(plan.telegram_chat_id)<Number(plan.session.nombre_joueurs)-1);
return [{json:{accepte,reponse:accepte?plan.reponse:'Toutes les places sont prises. Votre inscription n’a pas été conservée.'}}];

const plan=$('Planifier la partie').first().json;
let reponse=plan.reponse;
if(plan.inscrire) reponse=$('Verifier la place disponible').first().json.reponse;
return [{json:{session_id:plan.session_id,telegram_chat_id:plan.telegram_chat_id,reponse,origine:'commande',type_message:'commande',
  telegram_html:reponse.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}}];

// L'identité est fixée côté serveur. Elle n'est jamais acceptée depuis le navigateur.
const ORGANISATEUR='6644853325';
const requete=$input.first().json,body=requete.body||{};
const origine=String(requete.headers?.origin||'');
const origines=['https://thecat78500.github.io','http://127.0.0.1:8765','http://localhost:8765'];
const action=typeof body.action==='string'?body.action:'';
let erreur='';
if(origine&&!origines.includes(origine))erreur='Origine non autorisée.';
else if(!['etat','creer','demarrer','fin'].includes(action))erreur='Action non autorisée.';
const uuid=typeof body.requete_id==='string'?body.requete_id:'';
if(!erreur&&action!=='etat'&&!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(uuid))erreur='Identifiant de requête invalide.';
let texte='/statut';
if(action==='creer'){
 const nombre=String(body.nombre_joueurs||''),affaire=String(body.scenario_id||'');
 if(!/^(?:[4-9]|10)$/.test(nombre)||!/^(?:[1-9]|10)$/.test(affaire))erreur='Choisissez 4 à 10 joueurs et une affaire de 1 à 10.';
 texte=`/creer ${nombre} ${affaire}`;
}else if(action==='demarrer'||action==='fin'){
 const code=typeof body.partie==='string'?body.partie.trim().toUpperCase():'';
 if(!/^M[A-Z0-9]{7}$/.test(code))erreur='Code de partie invalide.';
 texte=`/${action} ${code}`;
}
return [{json:{telegram_chat_id:ORGANISATEUR,telegram_message_id:'WEB-'+uuid,prenom:'David',texte,action_web:action,erreur_web:erreur}}];

const source=$('Normaliser Telegram').first().json;
const plan=$('Planifier la partie').first().json;
const sessions=$('Relire les parties').all().map(i=>i.json);
const session=sessions.filter(s=>String(s.organisateur_chat_id)===source.telegram_chat_id&&['accueil','en_cours'].includes(s.statut)).sort((a,b)=>Number(b.id||0)-Number(a.id||0))[0];
let doublon=false;try{doublon=$('Verifier evenement Telegram').all().some(i=>i.json.telegram_message_id)}catch{}
const message=doublon?'Cette demande a déjà été reçue. L’état actuel a été relu, sans répéter l’action.':plan.reponse;
if(!session)return [{json:{ok:true,message,partie:null,joueurs:[],progression:{initialise:false,resolues:0,total:5,active:null,carnet:[]}}}];
const participants=$('Relire les participants').all().map(i=>i.json).filter(j=>j.session_id===session.session_id).sort((a,b)=>Number(a.id||0)-Number(b.id||0));
const uniques=new Map();for(const j of participants){if(!uniques.has(String(j.telegram_chat_id)))uniques.set(String(j.telegram_chat_id),j)}
const owner=uniques.get(String(session.organisateur_chat_id));
const invites=[...uniques.values()].filter(j=>String(j.telegram_chat_id)!==String(session.organisateur_chat_id)).slice(0,Number(session.nombre_joueurs)-1);
const joueurs=[...(owner?[owner]:[]),...invites].map(j=>({prenom:String(j.prenom||'Invité').slice(0,80)}));
const lignes=$input.all().map(i=>i.json).filter(e=>e.session_id===session.session_id);
let active=null,carnet=[],initialise=false;
if(session.statut==='en_cours'&&lignes.length===5&&[1,2,3,4,5].every(n=>lignes.filter(e=>e.etape===String(n)).length===1)){
  const etapes=lignes.sort((a,b)=>Number(a.etape)-Number(b.etape));
  if(etapes.every(e=>['resolue','a_resoudre'].includes(e.statut))){
    initialise=true;
    const premiere=etapes.findIndex(e=>e.statut!=='resolue');
    carnet=etapes.slice(0,premiere<0?5:premiere).map(e=>({etape:Number(e.etape),titre:String(e.titre),reponse:String(e.solution)}));
    if(premiere>=0){const e=etapes[premiere];active={etape:Number(e.etape),titre:String(e.titre),enonce:String(e.enonce)}}
  }
}
// Liste blanche explicite : ne jamais renvoyer les lignes brutes des tables.
return [{json:{ok:true,message,partie:{code:session.session_id,scenario_id:Number(session.scenario_id),statut:session.statut,nombre_joueurs:Number(session.nombre_joueurs)},joueurs,
  progression:{initialise,resolues:carnet.length,total:5,active,carnet},actualise_a:new Date().toISOString()}}];
